window.kbPageData["views/entry/k-1cbc3ec8b58a4454"] = {"key":"entry/k-1cbc3ec8b58a4454","state":{"route":"entry/k-1cbc3ec8b58a4454"},"node":{"id":"k-1cbc3ec8b58a4454","mode":"k","title":"体系化推进各层级各领域党组织建设。","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"1.体系化推进各层级各领域党组织建设。\n严密的组织体系，是马克思主义政党的优势所在、力量所在。党的力量来自组织，党\n的全面领导、党的全部工作要靠党的坚强组织体系去实现。我们党历来高度重视组织的统\n一和巩固，伴随着革命、建设、改革的历史进程，建立起包括党的中央组织、地方组织、\n基层组织在内的严密组织体…","sources":[{"id":"42eca6d3cff14a84","label":"体系化推进各层级各领域党组织建设。","topic":"党政制度与理论","category":"非时政","text":"1.体系化推进各层级各领域党组织建设。\n严密的组织体系，是马克思主义政党的优势所在、力量所在。党的力量来自组织，党\n的全面领导、党的全部工作要靠党的坚强组织体系去实现。我们党历来高度重视组织的统\n一和巩固，伴随着革命、建设、改革的历史进程，建立起包括党的中央组织、地方组织、\n基层组织在内的严密组织体系。\n《决定》从 6 个方面作出部署：一是发挥中央和国家机关党组织表率作用。深化政治\n机关建设，把中央和国家机关建设成为讲政治、守纪律、负责任、有效率的模范机关。二\n是强化地方党委功能。强调地方党委在本地区履行把方向、管大局、作决策、保落实职责，\n把地方党委建设成为坚决听从党中央指挥、执行有力、管理严格、班子团结、风气纯正的\n坚强组织。三是统筹推进各领域基层党组织建设。强化大抓基层鲜明导向，深入推进抓党\n建促乡村全面振兴，加强城市街道、社区党建工作，深化党建引领基层治理和基层政权建\n设。四是突出抓好新兴领域党的建设。深化拓展新经济组织、新社会组织、新就业群体党\n的组织覆盖和工作覆盖，增强党在新兴领域号召力凝聚力影响力。五是加强党员队伍建\n设。坚持把政治标准放在首位，提高发展党员质量，优化党员队伍结构，强化党员教育管\n理，完善和落实党员作用发挥机制。六是完善党的各级组织贯通机制。坚持抓好本级、带\n动下级，层层抓落实，做实党委（党组）书记抓基层党建工作述职评议考核，推动党的各\n级组织全面进步、全面过硬。","source":{"doc":"41195a191a57c1c36332","first":16,"last":17,"page":16,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-1cbc3ec8b58a4454":[]}};
